import { test, expect } from "./fixtures.ts";
import { liveYears, PROJECTS, SCORES_MEASURED, siteHref } from "../src/data/projects.ts";

// The page per project, /projects/<id>/, generated by scripts/pages.ts.
test.beforeEach(async ({ page }) => {
  await page.addInitScript(() => localStorage.setItem("consent", "denied"));
});

for (const [i, project] of PROJECTS.entries()) {
  test(`${project.name}'s page loads with its details and screenshots`, async ({ page }) => {
    const errors: string[] = [];
    page.on("pageerror", error => errors.push(error.message));
    page.on("console", message => {
      if (message.type() === "error") errors.push(message.text());
    });

    const path = `/projects/${project.id}/`;
    await page.goto(path);
    await expect(page).toHaveTitle(`${project.name} — Mark Eriksson`);
    await expect(page.getByRole("heading", { level: 1 })).toHaveText(`${project.name}_`);
    await expect(page.locator('link[rel="canonical"]')).toHaveAttribute("href", new RegExp(`${path}$`));
    await expect(page.locator('meta[property="og:image"]')).toHaveAttribute(
      "content",
      new RegExp(`/img/projects/${project.id}\\.jpg$`),
    );
    if (project.summary) await expect(page.locator(".lede")).toHaveText(project.summary);

    // Both screenshots get a srcset from project-page.ts and finish loading.
    for (const view of ["desktop", "mobile"]) {
      const img = page.locator(`[data-shot="${view}"]`);
      await img.scrollIntoViewIfNeeded();
      await expect(img).toHaveAttribute("srcset", /\.webp \d+w/);
      await expect.poll(() => img.evaluate((el: HTMLImageElement) => el.complete && el.naturalWidth > 0)).toBe(true);
    }

    // Previous and next wrap around the list.
    const prev = PROJECTS[(i - 1 + PROJECTS.length) % PROJECTS.length];
    const next = PROJECTS[(i + 1) % PROJECTS.length];
    await expect(page.locator('[rel="prev"]')).toHaveAttribute("href", `/projects/${prev.id}/`);
    await expect(page.locator('[rel="next"]')).toHaveAttribute("href", `/projects/${next.id}/`);

    await page.waitForLoadState("networkidle");
    expect(errors).toEqual([]);
  });
}

test("scores show only for projects that have them", async ({ page }) => {
  const scored = PROJECTS.find(project => project.scores)!;
  await page.goto(`/projects/${scored.id}/`);
  await expect(page.getByRole("heading", { name: `// GTmetrix, ${SCORES_MEASURED}` })).toBeVisible();
  await expect(page.locator(".case-scores .stat").first()).toHaveText(`${scored.scores!.performance}%`);

  const unscored = PROJECTS.find(project => !project.scores)!;
  await page.goto(`/projects/${unscored.id}/`);
  await expect(page.locator(".case-scores")).toHaveCount(0);
});

test("a retired project's page links to its archived copy and its replacement, and back", async ({ page }) => {
  const retired = PROJECTS.find(project => project.retired?.replacedBy)!;
  const replacement = PROJECTS.find(project => project.id === retired.retired!.replacedBy)!;

  await page.goto(`/projects/${retired.id}/`);
  await expect(page.locator(".eyebrow").first()).toContainText("retired");
  await expect(page.getByRole("link", { name: "View archived copy" })).toHaveAttribute("href", siteHref(retired)!);
  await expect(page.locator(".case-facts")).toContainText(liveYears(retired)!);
  await expect(page.locator(".case-scores")).toHaveCount(0);
  await page.locator(".case-note").getByRole("link", { name: replacement.name }).click();

  await expect(page).toHaveURL(new RegExp(`/projects/${replacement.id}/$`));
  await expect(page.locator(".case-note").getByRole("link", { name: retired.name })).toHaveAttribute(
    "href",
    `/projects/${retired.id}/`,
  );
});

test("the gallery's Details button opens the project's page", async ({ page }) => {
  const project = PROJECTS[2];
  await page.goto(`/#projects/${project.id}`);
  await page.getByRole("link", { name: `${project.name} details` }).click();
  await expect(page).toHaveURL(new RegExp(`/projects/${project.id}/$`));
  await expect(page.getByRole("heading", { level: 1 })).toHaveText(`${project.name}_`);
});

test("the back link returns to the project in the gallery", async ({ page }) => {
  const project = PROJECTS[4];
  await page.goto(`/projects/${project.id}/`);
  await page.getByRole("link", { name: "~/projects" }).click();
  await expect(page).toHaveURL(new RegExp(`/#projects/${project.id}$`));
  await expect(page.locator("[data-name]")).toHaveText(project.name);
});

test("the sitemap lists every project page", async ({ request }) => {
  const sitemap = await (await request.get("/sitemap.xml")).text();
  for (const project of PROJECTS) expect(sitemap).toContain(`/projects/${project.id}/</loc>`);
});
